#!/usr/bin/env python3
"""Plan cleanup of generated bytecode and completed owned-test Wine prefixes only.

Dry run by default. Does not prune models, replays, evidence, compilers, build
libraries or game installations. Every applied deletion is journaled first.
"""
import argparse
from datetime import datetime, timezone
import fcntl
import json
import os
from pathlib import Path
import shutil

ROOT = Path(__file__).resolve().parents[1]
PROTECTED_SUFFIXES = {'.tmhyb', '.tmppo', '.pt', '.pth', '.checkpoint', '.gbx'}
SOURCE_DIRS = ('scripts', 'integrations', 'apps', 'native/src', 'native/tests', 'rust')


def active_prefixes():
    prefixes = set()
    for proc in Path('/proc').iterdir():
        if not proc.name.isdigit():
            continue
        try:
            for item in (proc / 'environ').read_bytes().split(b'\0'):
                if item.startswith(b'WINEPREFIX='):
                    prefixes.add(Path(os.fsdecode(item.split(b'=', 1)[1])).resolve())
        except (OSError, ValueError):
            continue
    return prefixes


def plain_directory(root, path):
    """Reject a symlink at any component; do not follow a relocated test tree."""
    try:
        relative = path.relative_to(root)
    except ValueError:
        return False
    current = root
    for part in relative.parts:
        current /= part
        if current.is_symlink():
            return False
    return path.is_dir()


def entries(path):
    for base, dirs, files in os.walk(path, followlinks=False):
        dirs[:] = [d for d in dirs if not (Path(base) / d).is_symlink()]
        for name in files:
            yield Path(base) / name


def completed(prefix):
    report = prefix.parent / 'owned-windows-final.json'
    try:
        doc = json.loads(report.read_text())
        if doc.get('ownedDetour') is True and doc.get('gameAccessed') is False:
            return True
    except (OSError, ValueError):
        pass
    progress = prefix.parent / 'owned-pipeline.args.status'
    try:
        return progress.read_text().rstrip().endswith('fixture_complete')
    except OSError:
        return False


def eligible(root, path, kind, active):
    if not plain_directory(root, path):
        return False
    files = list(entries(path))
    if kind == 'python-bytecode':
        return path.name == '__pycache__' and any(
            path.is_relative_to(root / base) for base in SOURCE_DIRS) and all(
                p.is_file() and not p.is_symlink() and p.suffix in ('.pyc', '.pyo') for p in files)
    if kind != 'owned-wine-prefix' or path.parent.parent != root / 'local/recon':
        return False
    if path.name != 'owned-wine-prefix' or path.resolve() in active or not completed(path):
        return False
    if not all((path / f).is_file() for f in ('system.reg', 'user.reg')) or \
            not (path / 'drive_c/windows').is_dir():
        return False
    return not any(p.suffix.lower() in PROTECTED_SUFFIXES for p in files)


def plan(root, active=None):
    active = active_prefixes() if active is None else active
    candidates = []
    for base in SOURCE_DIRS:
        folder = root / base
        if plain_directory(root, folder):
            # os.walk never follows symlinks into external sources or game files.
            for directory, dirs, _ in os.walk(folder, followlinks=False):
                dirs[:] = [d for d in dirs if not (Path(directory) / d).is_symlink()]
                if '__pycache__' in dirs:
                    candidates.append((Path(directory) / '__pycache__', 'python-bytecode'))
                    dirs.remove('__pycache__')
    recon = root / 'local/recon'
    if plain_directory(root, recon):
        candidates.extend((p, 'owned-wine-prefix') for p in recon.glob('*/owned-wine-prefix'))
    result = []
    for path, kind in sorted(candidates):
        if eligible(root, path, kind, active):
            files = list(entries(path))
            stat = path.stat()
            result.append({'path': str(path.relative_to(root)), 'kind': kind,
                           'files': len(files), 'bytes': sum(p.lstat().st_size for p in files),
                           'device': stat.st_dev, 'inode': stat.st_ino})
    return result


def apply(root, items, journal, active_provider=active_prefixes):
    removed = []
    with journal.open('x') as stream:
        for item in items:
            path = root / item['path']
            if '..' in Path(item['path']).parts or not eligible(root, path, item['kind'], active_provider()):
                raise RuntimeError(f"Cleanup eligibility changed: {item['path']}")
            stat = path.stat()
            if (stat.st_dev, stat.st_ino) != (item['device'], item['inode']):
                raise RuntimeError(f"Directory changed: {item['path']}")
            stream.write(json.dumps({'action': 'remove-generated-directory', **item}) + '\n')
            stream.flush()
            os.fsync(stream.fileno())
            shutil.rmtree(path)
            removed.append(item)
            stream.write(json.dumps({'removed': item['path']}) + '\n')
            stream.flush()
    return removed


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--apply', action='store_true')
    args = parser.parse_args()
    cleanup = ROOT / 'local/cleanup'
    if args.apply:
        cleanup.mkdir(parents=True, exist_ok=True)
        with (cleanup / 'generated-cleanup.lock').open('a') as lock:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
            items = plan(ROOT)
            stamp = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S.%fZ')
            output = cleanup / ('generated-' + stamp)
            output.mkdir()
            (output / 'plan.json').write_text(json.dumps(items, indent=2) + '\n')
            removed = apply(ROOT, items, output / 'deletions.jsonl')
            report = {'removedDirectories': len(removed), 'removedBytes': sum(x['bytes'] for x in removed),
                      'scope': 'generated bytecode and completed inactive owned-test prefixes only'}
            (output / 'result.json').write_text(json.dumps(report, indent=2) + '\n')
            print(json.dumps({**report, 'journal': str(output)}, indent=2))
    else:
        items = plan(ROOT)
        print(json.dumps({'apply': False, 'directories': len(items),
                          'logicalBytes': sum(x['bytes'] for x in items), 'items': items}, indent=2))


if __name__ == '__main__':
    main()
